INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('hero', 'arrival', 0, 'Five minutes from the runway', '', 'Sinamangal, Kathmandu — close enough to hear the last boarding call and still make it.', '', '/media/hero/arrival.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('hero', 'rooms', 1, 'A bed built for landing days', '', 'Warm wood, thick curtains, hot water on demand — the duplex king, turned down and waiting.', '', '/media/hero/rooms.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('hero', 'breakfast', 2, 'Breakfast, the Thakali way', '', 'A full spread from seven — eggs, fruit, toast and tea, laid out for early flights and slow mornings alike.', '', '/media/hero/breakfast.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('hero', 'desk', 3, 'Someone at the desk, always', '', 'Late check-ins, early cabs — reception at Hotel Thakali Inn never goes dark.', '', '/media/hero/desk.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('service', 'rooms', 0, 'Rooms', 'Stay', 'Warm wood, pressed linen, a window that actually opens — quiet enough for the night before a flight.', '/rooms', '/media/services/rooms.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('service', 'breakfast', 1, 'Breakfast', 'Buffet', 'Eggs, toast, sausage and fresh fruit, laid out hot from seven — with milk tea alongside.', '/breakfast', '/media/services/breakfast.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('service', 'amenities', 2, 'Amenities', '', 'Everything the stay needs, nothing it doesn''t.', '/amenities', '/media/services/amenities.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('service', 'gallery', 3, 'Gallery', '', 'The rooms, the courtyard, the desk — as they actually look.', '/gallery', '/media/services/gallery.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('service', 'contact', 4, 'Contact', 'Always', 'Late check-ins, early cabs, a number that actually answers.', '/contact', '/media/services/contact.jpg', '', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('room', 'deluxe-double', 0, 'Deluxe Double', 'Sleeps 2, plus a child', 'Two beds with a lamp between them and a framed peak above. Wood floors, blackout curtains, and walls built for a road that never quite sleeps.', '', '/media/rooms/deluxe-double.jpg', '', '{"count":"9 rooms of this type","meta":["Two single beds"],"specs":[["Beds","Two single beds"],["Sleeps","2 guests — max 2 adults, 1 child"],["Rooms","9 of this type"]]}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('room', 'deluxe-king', 1, 'Deluxe King', 'Sleeps 2, plus a child', 'One wide bed, two armchairs and a low table by the window — the kettle already filled. Room enough to unpack in, not just sleep in.', '', '/media/rooms/deluxe-king.jpg', '', '{"count":"7 rooms of this type","meta":["King bed","Sitting area"],"specs":[["Beds","One king bed"],["Sleeps","2 guests — max 2 adults, 1 child"],["Rooms","7 of this type"]]}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('room', 'family', 2, 'Family Room', 'Sleeps 4, up to 3 adults', 'A king and a single under a wall of prints, with floor left over for the bags. Only two of them in the building, so ask early.', '', '/media/rooms/family.jpg', '', '{"count":"2 rooms of this type","meta":["King + single","Dining area"],"specs":[["Beds","One king bed and one single (100 cm)"],["Sleeps","4 guests — max 3 adults, 3 children"],["Rooms","2 of this type"]]}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'signage', 0, 'Off the Road', 'Sinamangal', 'The sign is the landmark — hotel and restaurant on one board, hung off the first floor over the pavement. Look up for it; the doorway underneath is easy to walk straight past.', '', '/media/gallery/signage.jpg', '/media/gallery/signage.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'arrival', 1, 'Reception', 'Front desk', 'The desk is staffed through the night, which is the only thing that matters when the flight lands at two in the morning. The airport is 950 m up the road.', '', '/media/gallery/arrival.jpg', '/media/gallery/arrival.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'lobby', 2, 'The Waiting Room', 'Ground floor', 'Red floor, low chairs, and somewhere to sit with the bags while a room is turned over. Most people meet their driver here.', '', '/media/gallery/lobby.jpg', '/media/gallery/lobby.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'corridor', 3, 'The Corridor', 'Doors off it', 'Rooms open off a short passage rather than a long hotel spine, so there is never far to carry anything. A door left ajar is how most of them are found.', '', '/media/gallery/corridor.jpg', '/media/gallery/corridor.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'rooms', 4, 'The Rooms', 'Eighteen of them', 'Three types across two floors — a double, a king, and two family rooms. Wood underfoot, curtains that actually black out, and walls built for a road that never quite sleeps.', '', '/media/gallery/rooms.jpg', '/media/gallery/rooms.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'bedside', 5, 'The Bedside', 'Lamp and line', 'A reading lamp on a swing arm, a phone through to the desk, and a framed print of the mountains most guests are on their way to.', '', '/media/gallery/bedside.jpg', '/media/gallery/bedside.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'window', 6, 'The Window', 'Two chairs', 'Curtains to the floor, two low chairs and a table between them. This is the corner of the room people actually sit in.', '', '/media/gallery/window.jpg', '/media/gallery/window.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'minibar', 7, 'The Minibar', 'Under the television', 'Water, soft drinks, a beer and a shelf of snacks, inside the cabinet below the television. Nothing in it needs a phone call first.', '', '/media/gallery/minibar.jpg', '/media/gallery/minibar.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'bathrooms', 8, 'The Bathrooms', 'One per room', 'Private to every room. A wide mirror, a long vanity, and enough counter left over to put a wash bag down on.', '', '/media/gallery/bathrooms.jpg', '/media/gallery/bathrooms.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'dining', 9, 'The Dining Hall', 'Seven to ten', 'Tables laid from early morning. It fills at seven, empties by ten, and is one of the quietest rooms in the building in between.', '', '/media/gallery/dining.jpg', '/media/gallery/dining.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'buffet', 10, 'The Buffet', 'Hot counter', 'Chafing dishes along the back wall, tables pulled up in front of them. Eggs, sausage, fruit and toast are laid out here and you help yourself.', '', '/media/gallery/buffet.jpg', '/media/gallery/buffet.mp4', '{}');
INSERT INTO content (section, slug, position, title, tag, body, href, image, video, extra) VALUES ('gallery', 'breakfast', 11, 'Breakfast', 'Thakali, plated', 'Dal, rice, greens, and the pickle that makes the plate. The Thakali set is the one thing cooked to order, which is why it takes a minute.', '', '/media/gallery/breakfast.jpg', '/media/gallery/breakfast.mp4', '{}');
